#!/usr/bin/env python3

# Test the original col_insert test from sympy test suite
import sys
sys.path.insert(0, '/private/tmp/swe-bench-test/sympy_nomem_2')

from sympy.matrices.common import _MinimalMatrix, MatrixShaping
from sympy.matrices import Matrix
from sympy.utilities.iterables import flatten

class ShapingOnlyMatrix(_MinimalMatrix, MatrixShaping):
    pass

def zeros_Shaping(n):
    return ShapingOnlyMatrix(n, n, lambda i, j: 0)

def test_col_insert():
    print("Running original sympy col_insert test...")
    c4 = Matrix([4, 4, 4])
    for i in range(-4, 5):
        l = [0, 0, 0]
        l.insert(i, 4)
        result = flatten(zeros_Shaping(3).col_insert(i, c4).row(0).tolist())
        print(f"i={i}: expected={l}, got={result}, match={result == l}")
        assert result == l
    print("✅ Original test passed!")

if __name__ == "__main__":
    test_col_insert()

